package com.coffeeshop.controller;import com.coffeeshop.dto.DiscountCommands;import com.coffeeshop.model.DiscountModels.Discount;import com.coffeeshop.service.DiscountService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.geometry.Insets;import javafx.scene.control.*;import javafx.scene.layout.GridPane;import java.math.BigDecimal;import java.time.*;import java.util.*;import java.util.concurrent.CompletableFuture;public final class DiscountController{private final DiscountService service;@FXML private TextField searchField;@FXML private ChoiceBox<String>activeFilter;@FXML private TableView<Discount>discountTable;@FXML private TableColumn<Discount,String>codeColumn,nameColumn,typeColumn,valueColumn,validityColumn,statusColumn;@FXML private Label messageLabel;@FXML private Button editButton,activeButton;public DiscountController(DiscountService s){service=Objects.requireNonNull(s);}@FXML private void initialize(){codeColumn.setCellValueFactory(v->text(v.getValue().code()));nameColumn.setCellValueFactory(v->text(v.getValue().name()));typeColumn.setCellValueFactory(v->text(v.getValue().type().replace('_',' ')));valueColumn.setCellValueFactory(v->text(v.getValue().value().toPlainString()+("PERCENTAGE".equals(v.getValue().type())?"%":"")));validityColumn.setCellValueFactory(v->text(validity(v.getValue())));statusColumn.setCellValueFactory(v->text(v.getValue().currentlyValid(LocalDateTime.now())?"Available":v.getValue().active()?"Outside validity":"Inactive"));activeFilter.getItems().setAll("Active","Inactive","All");activeFilter.setValue("Active");searchField.textProperty().addListener((o,a,b)->refresh());activeFilter.valueProperty().addListener((o,a,b)->refresh());discountTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->selection(b));refresh();}@FXML private void refresh(){Boolean active="All".equals(activeFilter.getValue())?null:"Active".equals(activeFilter.getValue());CompletableFuture.supplyAsync(()->service.discounts(searchField.getText(),active)).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load discounts.");return;}discountTable.getItems().setAll(v);messageLabel.setText(v.isEmpty()?"No discounts match the filters.":"");selection(discountTable.getSelectionModel().getSelectedItem());}));}@FXML private void add(){editor(null).ifPresent(this::save);}@FXML private void edit(){Discount d=discountTable.getSelectionModel().getSelectedItem();if(d!=null)editor(d).ifPresent(this::save);}@FXML private void toggle(){Discount d=discountTable.getSelectionModel().getSelectedItem();if(d!=null)write(()->service.setActive(d,!d.active()),"Discount updated.");}private Optional<DiscountCommands.Save>editor(Discount d){Dialog<DiscountCommands.Save>x=new Dialog<>();x.setTitle(d==null?"Add discount":"Edit discount");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);x.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,save);TextField code=f(d==null?null:d.code()),name=f(d==null?null:d.name()),value=f(d==null?null:d.value().toPlainString());ComboBox<String>type=new ComboBox<>();type.getItems().setAll("PERCENTAGE","FIXED_AMOUNT");type.setValue(d==null?"PERCENTAGE":d.type());DatePicker from=new DatePicker(d==null||d.validFrom()==null?null:d.validFrom().toLocalDate()),until=new DatePicker(d==null||d.validUntil()==null?null:d.validUntil().toLocalDate());CheckBox active=new CheckBox("Active");active.setSelected(d==null||d.active());GridPane g=new GridPane();g.setHgap(12);g.setVgap(8);g.setPadding(new Insets(8));field(g,0,"Code",code);field(g,1,"Name",name);field(g,2,"Type",type);field(g,3,"Value",value);field(g,4,"Valid from",from);field(g,5,"Valid until",until);g.add(active,1,6);x.getDialogPane().setContent(g);x.setResultConverter(b->{if(b!=save)return null;BigDecimal n;try{n=new BigDecimal(value.getText());}catch(Exception e){n=null;}return new DiscountCommands.Save(d==null?null:d.id(),code.getText(),name.getText(),type.getValue(),n,from.getValue()==null?null:from.getValue().atStartOfDay(),until.getValue()==null?null:until.getValue().plusDays(1).atStartOfDay(),active.isSelected(),d==null?null:d.version());});return x.showAndWait();}private void save(DiscountCommands.Save q){write(()->service.save(q),"Discount saved.");}private void write(Runnable r,String ok){CompletableFuture.runAsync(r).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText(ok);}else messageLabel.setText(message(e));}));}private void selection(Discount d){editButton.setDisable(d==null);activeButton.setDisable(d==null);activeButton.setText(d==null||d.active()?"Deactivate":"Activate");}private static String validity(Discount d){return (d.validFrom()==null?"Any time":d.validFrom().toLocalDate().toString())+" – "+(d.validUntil()==null?"No end":d.validUntil().minusNanos(1).toLocalDate().toString());}private static TextField f(String s){return new TextField(s==null?"":s);}private static void field(GridPane g,int r,String n,Control c){g.add(new Label(n),0,r);c.setMaxWidth(Double.MAX_VALUE);g.add(c,1,r);}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to save discount.";}}
